import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong(), removals = nextLong();
        String s = next();
        long[] counts = new long[26];
        for (int i = 0; i < s.length(); i++) counts[s.charAt(i) - 'a']++;
        PriorityQueue<Long> heap = new PriorityQueue<>(Comparator.reverseOrder());
        for (long c : counts) if (c > 0) heap.add(c);
        // Removing one copy of a letter with frequency f saves 2f - 1, so always shrink the largest.
        for (long k = 0; k < Math.min(removals, n); k++) {
            long largest = heap.poll();
            if (largest > 1) heap.add(largest - 1);
        }
        long cost = 0;
        for (long c : heap) cost += c * c;
        System.out.println(cost);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

// maxHeap is a max-heap of letter frequencies.
type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, removals := nextInt(), nextInt()
	s := nextToken()
	var counts [26]int64
	for i := 0; i < len(s); i++ {
		counts[s[i]-'a']++
	}
	h := &maxHeap{}
	for _, c := range counts {
		if c > 0 {
			*h = append(*h, c)
		}
	}
	heap.Init(h)
	// Removing one copy of a letter with frequency f saves 2f - 1, so always shrink the largest.
	for k := int64(0); k < min(removals, n); k++ {
		largest := heap.Pop(h).(int64)
		if largest > 1 {
			heap.Push(h, largest-1)
		}
	}
	var cost int64
	for _, c := range *h {
		cost += c * c
	}
	fmt.Println(cost)
}
